package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes RATE_SET to the audit file once the rate is stored, ending with from=<date> when it has a from-date, then to=<date> when it has a to-date. Then writes the
 * figures the change moved (see Rollup). */
public class RecordRateSet {
    public void record(@Val Rate rate, @Val RateValues values, @Val RollupBefore before, Rollup rollup, Audit audit) {
        audit.record("RATE_SET sheet=" + rate.sheetId() + " by=" + values.by() + " grade=" + rate.grade()
                + " rate=" + rate.rate().toPlainString() + (rate.from() == null ? "" : " from=" + rate.from())
                + (rate.to() == null ? "" : " to=" + rate.to()));
        rollup.record(rate.sheetId(), values.by(), before);
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.hq.app.statement.SheetAsOf;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's rates, by grade, then those of its parent, the parent's parent, up to three levels up, then those of
 *  the sheet it was cloned from and its parents and source (see RateRepository#chain; each with its level), which
 *  apply to a grade on a date the sheet has no rate for; read as of a date (see AsOf), the sheet's own as they stood then (see SheetAsOf) and those inherited from the parent it had then (see RateRepository#chainAsOf)
 *  as they are now (a parent keeps its own today, so the date
 *  says nothing of when its rates were stored). */
public class RespondWithRates {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(value = "asOf", required = false) String asOf, RateRepository rates,
            SettingRepository settings, ObjectResponse<List<RateResponse>> response) {
        LocalDate date = AsOf.parse(asOf);
        List<RateResponse> shown = new ArrayList<>();
        List<String> chain = date == null ? rates.chain(sheetId.trim()) : rates.chainAsOf(sheetId.trim(), date);
        if (date != null) {
            SheetAsOf sheet = SheetAsOf.read(chain.get(0), date, rates, settings);
            for (Rate rate : sheet.rates()) {
                shown.add(RateResponse.from(rate, 0, sheet.older(rate)));
            }
        }
        for (int level = date == null ? 0 : 1; level < chain.size(); level++) {
            for (Rate rate : rates.list(chain.get(level))) {
                shown.add(RateResponse.from(rate, level, rates.older(rate.sheetId(), rate.grade(), rate.from())));
            }
        }
        response.send(shown);
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the grade is A, B or C; the rate a percent 0.00 or more with up to two decimals;
 *  the from-date and to-date blank (none) or a date yyyy-MM-dd, the to-date not before the from-date. */
public class ValidateRate {
    private static final Set<String> GRADES = Set.of("A", "B", "C");
    private static final Pattern RATE = Pattern.compile("\\d{1,5}(\\.\\d{1,2})?");

    public void validate(@PathVariable("grade") String grade, @RequestBody RateRequest request, Out<RateValues> values)
            throws InvalidRateException {
        values.set(check(grade, request));
    }

    /** The rate form's rules: the grade's rate as set by the request, or refused. */
    static RateValues check(String grade, RateRequest request) throws InvalidRateException {
        String g = grade == null ? "" : grade.trim();
        if (!GRADES.contains(g)) {
            throw new InvalidRateException("Grade must be A, B or C");
        }
        String rate = request == null || request.rate() == null ? "" : request.rate().trim();
        if (!RATE.matcher(rate).matches()) {
            throw new InvalidRateException("The rate must be a percent 0.00 or more with up to two decimals");
        }
        LocalDate from = date(request.from(), "from");
        LocalDate to = date(request.to(), "to");
        if (from != null && to != null && to.isBefore(from)) {
            throw new InvalidRateException("The to-date must not be before the from-date");
        }
        return new RateValues(g, new BigDecimal(rate).setScale(2), from, to,
                request.by() == null ? "" : request.by().trim());
    }

    private static LocalDate date(String value, String name) throws InvalidRateException {
        String text = value == null ? "" : value.trim();
        if (text.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new InvalidRateException("The " + name + "-date must be a date yyyy-MM-dd");
        }
    }
}
