cat > $D/ValidateRetireGrade.java <<'EOF'
package net.officefloor.hq.app.grade;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the grade is A, B or C. */
public class ValidateRetireGrade {
    public void validate(@RequestBody RetireGradeRequest request, Out<RetireGradeValues> values) throws InvalidGradeException {
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        if (!GradeRepository.GRADES.contains(grade)) {
            throw new InvalidGradeException("Grade must be A, B or C");
        }
        values.set(new RetireGradeValues(grade, request.by() == null ? "" : request.by().trim()));
    }
}
EOF
cat > $D/RetireGrade.java <<'EOF'
package net.officefloor.hq.app.grade;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Retires the grade on the sheet; one already retired is refused. */
public class RetireGrade {
    public void retire(@PathVariable("sheetId") String sheetId, @Val RetireGradeValues values, GradeRepository grades)
            throws InvalidGradeException {
        String sheet = sheetId.trim();
        if (grades.isRetired(sheet, values.grade())) {
            throw new InvalidGradeException("Grade " + values.grade() + " is already retired");
        }
        grades.retire(sheet, values.grade());
    }
}
EOF
cat > $D/RecordGradeRetired.java <<'EOF'
package net.officefloor.hq.app.grade;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Writes GRADE_RETIRED to the audit file once the grade is retired. */
public class RecordGradeRetired {
    public void record(@PathVariable("sheetId") String sheetId, @Val RetireGradeValues values, Audit audit) {
        audit.record("GRADE_RETIRED sheet=" + sheetId.trim() + " by=" + values.by() + " grade=" + values.grade());
    }
}
EOF
cat > $D/GradeResponse.java <<'EOF'
